import React from 'react';
import styled from 'styled-components';
import useResizeObserver from 'use-resize-observer';

import { Grid } from '../../../../layouts-core/grid/Grid.js';

/**
 * @internal
 */
export interface ChartGridAreaProps {
  gridArea: string;
  children: (props: {
    availableWidth: number;
    availableHeight: number;
  }) => JSX.Element;
}

const StyledGridArea = /* @__PURE__ */ styled(Grid<'div'>)`
  box-sizing: content-box;
`;

/**
 * A grid area in the that automatically adjusts its size to fit its container.
 * @internal
 */
export const ChartGridArea = ({
  gridArea,
  children,
  ...rest
}: ChartGridAreaProps) => {
  const { width, height, ref } = useResizeObserver<HTMLDivElement>();

  return (
    <StyledGridArea
      ref={ref}
      gridItem
      justifyContent="center"
      gridArea={gridArea}
      {...rest}
    >
      {children({
        availableWidth: width ?? 0,
        availableHeight: height ?? 0,
      })}
    </StyledGridArea>
  );
};
